-- AlterTable
ALTER TABLE "DepartmentMember" ADD COLUMN     "description" TEXT,
ADD COLUMN     "order" INTEGER NOT NULL DEFAULT 0,
ADD COLUMN     "title" VARCHAR(100);

-- Copy the presidium titles and descriptions that the website used to hard-code.
UPDATE "DepartmentMember" AS m
SET "title" = p."title",
    "description" = p."description",
    "order" = p."order",
    "telegramTag" = COALESCE(NULLIF(btrim(m."telegramTag"), ''), p."telegramTag")
FROM (VALUES
  ('Дарʼя', 'Цвілюк', 'Голова Студради', 1, '@dariiatsvlk',
   'Очолює Студраду ФІОТ і представляє студентів у діалозі з деканатом, адміністрацією університету та партнерами. Координує роботу всіх департаментів, визначає пріоритети команди та захищає права й інтереси студентів. За посадою входить до Вченої ради факультету та до повного складу Студентської ради КПІ.'),
  ('Артем', 'Жмура', 'Перший заступник голови', 2, '@zhmurartm',
   'Права рука голови: допомагає в загальному керівництві Студрадою та координації департаментів, виконує доручення голови. Коли голови немає, веде засідання й виконує її обовʼязки, тож завжди має бути в курсі всіх поточних процесів.'),
  ('Діана', 'Хмелюк', 'Секретар', 3, '@diashockh',
   'Відповідає за документообіг Студради: веде протоколи засідань, упорядковує офіційні документи та підписує їх разом із головою. Дбає, щоб протоколи й рішення Студради оприлюднювалися вчасно й були доступні кожному. За відсутності голови та першого заступника виконує обовʼязки голови.'),
  ('Юлія', 'Михайленко', 'Заступниця голови з внутрішньої роботи', 4, '@yulchikme',
   'Опікується тим, як Студрада працює зсередини: допомагає голові координувати департаменти, налагоджує звʼязок між командами та стежить, щоб спільні завдання не губилися між ними. Тримає голову в курсі справ у своєму напрямі.'),
  ('Марина', 'Омельяненко', 'Заступниця голови з внутрішньої роботи', 5, '@quekpiko',
   'Разом із Юлією Михайленко опікується внутрішньою роботою Студради: допомагає вибудовувати процеси всередині організації, щоб департаментам було простіше планувати й узгоджувати спільні справи. Виконує доручення голови й першого заступника.'),
  ('Ілля', 'Никитяк', 'Заступник голови із зовнішньої роботи', 6, '@ilya_nykytyak',
   'Відповідає за звʼязки Студради ФІОТ за межами факультету: співпрацю з іншими студентськими радами й організаціями та структурами університету. Допомагає голові представляти Студраду назовні та запускати спільні ініціативи з іншими студрадами.'),
  ('Максим', 'Бурлака', 'Заступник голови з технічного напрямку', 7, '@delnartik',
   'Опікується технічним боком роботи Студради: цифровими сервісами, ботами та іншими інструментами, якими користуються команда й студенти, а також технічним забезпеченням заходів. Допомагає автоматизувати рутину, щоб департаментам було простіше працювати.')
) AS p("firstName", "lastName", "title", "order", "telegramTag", "description")
WHERE lower(translate(btrim(m."firstName"), 'ʼ’', '''''')) = lower(translate(btrim(p."firstName"), 'ʼ’', ''''''))
  AND lower(translate(btrim(m."lastName"), 'ʼ’', '''''')) = lower(translate(btrim(p."lastName"), 'ʼ’', ''''''));
